# Static image assets served by the HTTP handler.
# These are base64-encoded images (JPEG, the logo PNG), decoded for serving.
import base64 as _b64

_LOGO_B64 = ""
_DIFFRACTION_BG_B64 = ""

_SPLASH_B64 = ""

STATIC_ASSETS = {
    "splash.jpg": ("image/jpeg", _b64.b64decode(_SPLASH_B64)),
    # CrystalPilot logo (PNG with transparency); logo.jpg stays as an alias because
    # installed launchers (windows/splash.html) poll /assets/logo.jpg
    "logo.png": ("image/png", _b64.b64decode(_LOGO_B64)),
    "logo.jpg": ("image/png", _b64.b64decode(_LOGO_B64)),
    "diffraction_bg.jpg": ("image/jpeg", _b64.b64decode(_DIFFRACTION_BG_B64)),
}
